impl Solution {
    pub fn count_monobit(n: i32) -> i32 {
        let mut count = 0;
        let mut current_monobit = 1;
        while current_monobit <= n {
            count += 1;
            current_monobit = current_monobit * 2 + 1;
        }
        count
    }
}

